import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int[] right = new int[26];
        boolean[] left = new boolean[26];
        int rightDistinct = 0, leftDistinct = 0;
        for (int i = 0; i < s.length(); i++) if (right[s.charAt(i) - 'a']++ == 0) rightDistinct++;
        long answer = 0;
        for (int i = 0; i + 1 < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (!left[c]) { left[c] = true; leftDistinct++; }
            if (--right[c] == 0) rightDistinct--;
            if (leftDistinct == rightDistinct) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	var s string
	fmt.Fscan(r, &s)
	var right [26]int
	var left [26]bool
	rightDistinct, leftDistinct := 0, 0
	for i := 0; i < len(s); i++ {
		if right[s[i]-'a'] == 0 {
			rightDistinct++
		}
		right[s[i]-'a']++
	}
	answer := 0
	for i := 0; i+1 < len(s); i++ {
		c := s[i] - 'a'
		if !left[c] {
			left[c] = true
			leftDistinct++
		}
		right[c]--
		if right[c] == 0 {
			rightDistinct--
		}
		if leftDistinct == rightDistinct {
			answer++
		}
	}
	fmt.Println(answer)
}
